/**
 * @payswap/provider-runtime — the Stripe operation-schemas READER (P24-1).
 *
 * The committed deterministic artifact (catalogue/operation-schemas.json,
 * generated by schema-generator.ts at dev time from the pinned spec) loaded
 * as module data — never fetched, never mutated. Same laws as census.ts's
 * inventory loading: pin verification happens at module load so drift fails
 * the whole package, loudly.
 */

import { STRIPE_OPENAPI_PIN } from './spec-pin.ts';
import { STRIPE_OPENAPI_PIN_COUNTS } from './spec-pin.ts';
import type {
  StripeOperationSchemaRecord,
  StripeOperationSchemasFile,
  StripeSchemaNode,
} from './schema-nodes.ts';

/** The pinned request-schema artifact, imported as committed data. */
import schemasJson from './operation-schemas.json' with { type: 'json' };

const SCHEMAS = schemasJson as StripeOperationSchemasFile;

/** Verify the committed schema artifact matches its own pin (fail-closed at load). */
function verifySchemasAgainstPin(): void {
  if (SCHEMAS.specInfoVersion !== STRIPE_OPENAPI_PIN.specInfoVersion) {
    throw new Error(
      `stripe operation-schemas version drift: file says ${SCHEMAS.specInfoVersion}, ` +
        `pin says ${STRIPE_OPENAPI_PIN.specInfoVersion}`,
    );
  }
  if (SCHEMAS.generatorId !== STRIPE_OPENAPI_PIN.schemaGeneratorId) {
    throw new Error(
      `stripe operation-schemas generator drift: file says ${SCHEMAS.generatorId}, ` +
        `pin says ${STRIPE_OPENAPI_PIN.schemaGeneratorId}`,
    );
  }
  if (SCHEMAS.operationCount !== STRIPE_OPENAPI_PIN_COUNTS.operations) {
    throw new Error(
      `stripe operation-schemas count drift: file says ${SCHEMAS.operationCount}, ` +
        `pin says ${STRIPE_OPENAPI_PIN_COUNTS.operations}`,
    );
  }
  if (SCHEMAS.unresolvableRefs.length > 0) {
    // The pinned spec resolves every request-surface ref; a non-empty ledger
    // means the artifact and the pin disagree — fail the load.
    throw new Error(
      `stripe operation-schemas carries unresolvable refs: ${SCHEMAS.unresolvableRefs.join(', ')}`,
    );
  }
}

verifySchemasAgainstPin();

/** The interned node table (shared by the validator). */
export const STRIPE_SCHEMA_DEFS: Readonly<Record<string, StripeSchemaNode>> = SCHEMAS.defs;

/** The artifact's fail-closed ledger (must be empty for the pinned spec). */
export const STRIPE_SCHEMA_UNREPRESENTABLE_OPERATIONS: readonly string[] =
  SCHEMAS.unrepresentableOperations;

/** Resolve one operation's request-schema record (undefined = unknown operation). */
export function stripeOperationSchema(operationId: string): StripeOperationSchemaRecord | undefined {
  return SCHEMAS.operations[operationId];
}

/** The artifact metadata (evidence records). */
export const STRIPE_SCHEMA_ARTIFACT_PIN = Object.freeze({
  specInfoVersion: SCHEMAS.specInfoVersion,
  generatorId: SCHEMAS.generatorId,
  operationCount: SCHEMAS.operationCount,
  defCount: Object.keys(SCHEMAS.defs).length,
  unresolvableRefCount: SCHEMAS.unresolvableRefs.length,
  unrepresentableOperationCount: SCHEMAS.unrepresentableOperations.length,
});
